def backoff(attempt, base=0.5, cap=30):
    return min(base * 2 ** attempt, cap)

_attempts = 0

def call(fn, retries=5):
    global _attempts
    for _ in range(retries):
        try:
            return fn()
        except Transient:
            _attempts += 1
            time.sleep(backoff(_attempts))
    raise

def test_backoff_is_capped():
    for i in range(10):
        call(flaky, retries=1)
    assert _attempts <= 5

